import java.util.HashSet;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        int[] rolls = {4, 2, 4, 6, 2, 1};
        Set<Integer> unique = new HashSet<>();
        for (int i = 0; i < rolls.length; i++) {
            unique.add(rolls[i]);
        }
        unique.remove(1);
        System.out.println("Distinct rolls: " + unique);
    }
}
